  'priv.keep.title': 'Private notes and health details',
  'priv.keep.body': 'Your medical card, access needs, allergy flag, child brief, journal, reflections, contacts, calm profile, family-at-home contacts and concierge chats stay on this device. If you turn this on, a copy is also kept in your account, so your phone and your computer show the same things.',
  'priv.keep.who': 'Only you can read the copy. It is not shown to the ship, the cruise line or the others on your booking, and it is not used for marketing. This version keeps it with your other account data, not yet in a separate encrypted store. A medical card is health information, so turn this on only if you are comfortable with that.',
  'priv.keep.label': 'Keep my private notes and health details on all my devices',
  'priv.keep.off': 'Turning this off deletes the copy in your account. This device keeps its own.',
  'priv.keep.pending': 'Nothing more will be sent. The copy in your account will be deleted as soon as the connection returns.',
  'priv.consents': 'What you have agreed to',
  'priv.region.title': 'Your rights in {region}',
  'priv.region.law.us': 'Privacy laws in the United States, such as the California CCPA and CPRA and the children’s privacy law COPPA, apply to what Princess keeps about you.',
  'priv.region.law.ca': 'Canada’s privacy law, PIPEDA, applies to what Princess keeps about you.',
  'priv.region.law.uk': 'The UK GDPR and the Data Protection Act apply to what Princess keeps about you.',
  'priv.region.law.eu': 'The EU GDPR applies to what Princess keeps about you.',
  'priv.region.law.au': 'The Australian Privacy Act applies to what Princess keeps about you.',
  'priv.right.access': 'See what Princess keeps about you. The access list below shows who has looked.',
  'priv.right.delete': 'Ask for it to be deleted. “Delete everything” below does this on this device.',
  'priv.right.correct': 'Correct anything that is wrong, from your account and booking screens.',
  'priv.right.portability': 'Take a copy with you. “Export” in Settings gives you one.',
  'priv.right.withdraw': 'Withdraw a consent at any time. The switches below take effect at once.',
  'priv.right.objectMarketing': 'Say no to marketing. It is off until you turn it on.',
  'priv.right.noSale': 'Princess does not sell or share your personal information, so there is nothing to opt out of.',
  'priv.region.age': 'In your region a parent or guardian decides about marketing and analytics for anyone under {age}.',
  'priv.region.change': 'Change where you live',
  'priv.region.parent': '{name} is under {age}. In your region a parent or guardian decides about marketing and analytics, so nothing is turned on for {name}.',
  'priv.child': '{name} is under 13. A parent or guardian decides, and nothing is turned on without them.',
  'priv.notYours': 'Only this person, or a parent for a child, can change these.',
