  'priv.c.improve': 'Help improve the app',
  'priv.c.improve.hint': 'Share which screens are used, with no name, booking or typed text. Off until you turn it on; turning it off forgets what was waiting to be sent. Separately, when the app hits a problem it tells the team what kind of problem it was, so it can be fixed, with no name, booking or typed text.',
