  'phone.progress': '{done} of {total} done',
  'phone.step.roaming': 'Turn off data roaming',
  'phone.step.roaming.why': 'Roaming is the usual cause of a surprise bill. Turn it off in your phone’s cellular settings.',
  'phone.step.backup': 'Save your boarding pass and key documents offline',
  'phone.step.backup.why': 'You may have no signal in the terminal or at sea.',
  'phone.step.airplane': 'Switch on airplane mode when you board',
  'phone.step.airplane.why': 'This stops the phone searching for a network, and it still lets you turn Wi-Fi back on.',
  'phone.step.wifi': 'Join the ship’s Wi-Fi, not a cell network',
  'phone.step.wifi.why': 'This app works on the ship’s free tier, so you do not need a paid plan to use it.',
  'phone.step.messages': 'Use the app’s free messaging',
  'phone.step.messages.why': 'Chat in the app costs nothing and works around the ship.',
  'phone.step.calls': 'Check your phone’s calling and text settings',
  'phone.step.calls.why': 'Calls and texts to and from a phone at sea may be charged by your carrier.',
  'phone.moment.beforeSailing': 'Before you sail',
  'phone.moment.beforeSailing.body': 'Turn off data roaming and save your documents offline while you still have a good signal.',
  'phone.moment.sailAway': 'Sail-away is a good time to check',
  'phone.moment.sailAway.body': 'Once the ship leaves port, a phone can connect to the ship’s cell service, which is charged as roaming. Use airplane mode and the ship’s Wi-Fi.',
  'phone.moment.atSea': 'At sea',
  'phone.moment.atSea.body': 'Keep airplane mode on and use the ship’s Wi-Fi. A phone that reconnects to a cell signal can be charged for it.',
  'phone.moment.inPort': 'In port',
  'phone.moment.inPort.body': 'A local network can connect without warning, and roaming can be expensive. Keep data roaming off, or use airplane mode with Wi-Fi.',
  'phone.wifiNote': 'Ship Wi-Fi plans and your data use are in',
  'phone.limits': 'This is guidance only. The app cannot see or change your phone’s settings, and the rates your carrier charges are theirs, not ours.',
  'phone.guard': 'Check your phone before you rely on it',
  'phone.guardBody': 'A phone that roams at sea can be charged heavily.',
