  'hub.guide.stranded': 'If you miss the ship',
  'hub.guide.stranded.s1': 'Stay calm: the ship’s agent in the port is expecting this can happen.',
  'hub.guide.stranded.s2': 'Call Guest Services and the port agent number on your port day page.',
  'hub.guide.stranded.s3': 'Keep your passport and boarding pass with you. Ask where the ship goes next.',
  'hub.guide.stranded.s4': 'Ask the agent about the line’s policy on getting to the next port at your own cost.',
  'hub.guide.stranded.s5': 'Keep every receipt and write down the time. The delay record below can go with an insurance claim.',
  'hub.guide.lostPhone': 'If you lose your phone or documents',
  'hub.guide.lostPhone.s1': 'Sign in from another device or ask at Guest Services to see your booking.',
  'hub.guide.lostPhone.s2': 'Ask for your boarding pass and Medallion to be reissued.',
  'hub.guide.lostPhone.s3': 'Keep a paper copy of your booking number, cabin, emergency contact and passport number somewhere safe.',
  'hub.guide.lostPhone.s4': 'Report a lost passport to the port agent or a consulate.',
  'hub.guide.outage': 'If the network or the app is down',
  'hub.guide.outage.s1': 'The app will say so on this page and list what still works.',
  'hub.guide.outage.s2': 'Use the deck map, your saved documents and your saved plan.',
  'hub.guide.outage.s3': 'Ask at Guest Services for anything you cannot do without a connection.',
  'hub.guide.outage.s4': 'What you do now is queued and sent when the connection returns.',
  'hub.guide.health': 'If there is a health notice',
  'hub.guide.health.s1': 'Read the notice on the Health page. It says what is happening and what is not.',
  'hub.guide.health.s2': 'Wash your hands often and use the sanitiser at venue doors.',
  'hub.guide.health.s3': 'If you feel unwell, stay in your cabin and call medical. Meals can be brought to you.',
  'hub.guide.health.s4': 'Ask Guest Services if you have a question. Nothing is hidden.',

